-- Apenas para testes locais (SQLite). Produção usa sql/schema.sql (MySQL).
CREATE TABLE usuarios (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, login TEXT NOT NULL UNIQUE, senha_hash TEXT NOT NULL, perfil TEXT NOT NULL, ativo INTEGER NOT NULL DEFAULT 1);
CREATE TABLE clientes (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, telefone TEXT, endereco TEXT NOT NULL, bairro TEXT, referencia TEXT);
CREATE TABLE rotas (id INTEGER PRIMARY KEY AUTOINCREMENT, data_rota TEXT NOT NULL, nome TEXT NOT NULL, criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE pedidos (id INTEGER PRIMARY KEY AUTOINCREMENT, cliente_id INTEGER NOT NULL REFERENCES clientes(id), vendedor TEXT NOT NULL, data_entrega TEXT NOT NULL, observacao TEXT, status TEXT NOT NULL DEFAULT 'aguardando', rota_id INTEGER REFERENCES rotas(id), ordem_rota INTEGER, criado_por INTEGER, criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE itens_pedido (id INTEGER PRIMARY KEY AUTOINCREMENT, pedido_id INTEGER NOT NULL REFERENCES pedidos(id) ON DELETE CASCADE, quantidade REAL NOT NULL, unidade TEXT NOT NULL, descricao TEXT NOT NULL, separado INTEGER NOT NULL DEFAULT 0, conferido INTEGER NOT NULL DEFAULT 0);
CREATE TABLE pendencias (id INTEGER PRIMARY KEY AUTOINCREMENT, pedido_id INTEGER NOT NULL REFERENCES pedidos(id) ON DELETE CASCADE, item_id INTEGER NOT NULL REFERENCES itens_pedido(id) ON DELETE CASCADE, observacao TEXT, resolvida INTEGER NOT NULL DEFAULT 0, criada_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
